template.content:
{#- ======================================== -#}
{#- ======================================== -#}
{#- Pre-declared parameters                  -#}
{#-    Should be provided by process         -#}
{#- ======================================== -#}
{%- declare status = null -%}
{%- declare information = null -%}

{#- ======================================================== -#}
{#- Check if all PIT Candidates have at least two satellites -#}
{#- ======================================================== -#}

{%- set NumPITCandidates = 0 -%}  

{%- for table in tables -%}

    {%- set NumSatellites = 0 -%}   

    {%- from table.entityTypes as PIT where PIT.name == "PIT Candidate" -%}

        {%- set NumPITCandidates = NumPITCandidates + 1 -%}

        {%- from table.relations as Rel -%}
            {%- from Rel.fkTable.entityTypes as Sat where Sat.name == "Satellite" -%}
                {%- set NumSatellites = NumSatellites + 1 -%}
            {%- endfrom -%}    
        {%- endfrom -%}

        {{table.name + " has relationships with " + NumSatellites + " satellites."}}{%br%}

        {%- if NumSatellites < 2 -%}
            {%- set status = -2 -%}
            {%- set information = "Validation failed" -%}
        {%- else -%}
            {%- if status != -2 -%}
                {%- set status = 1 -%}
            {%- endif -%}
            {%- set information = "All PIT Candidates validated successfully" -%}            
        {%- endif -%}

    {%- endfrom -%}

    {%- if NumPITCandidates == 0 -%}
        {%- set status = -1 -%}
        {%- set information = "No PIT Candidates" -%}          
    {%- endif -%}

{%- endfor -%}
